<?php
require_once __DIR__.'/bootstrap.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$a=$_POST['action']??'';
 if($a==='add'){
  $device=trim((string)$_POST['device_id']);$server=(int)$_POST['server_id'];$name=trim((string)$_POST['list_name']);$u=(string)$_POST['username'];$p=(string)$_POST['password'];$exp=trim((string)($_POST['expires_at']??''));$primary=isset($_POST['is_primary'])?1:0;
  if($primary)db()->prepare('UPDATE activations SET is_primary=0 WHERE device_id=?')->execute([$device]);
  db()->prepare('INSERT INTO activations(device_id,server_id,list_name,username_enc,password_enc,expires_at,is_primary) VALUES(?,?,?,?,?,?,?)')->execute([$device,$server,$name?:'Principal',encrypt_secret($u),encrypt_secret($p),$exp?:null,$primary]);
  $id=(int)db()->lastInsertId();audit_log('activation.create','activation',$id,'Dispositivo '.$device.' • lista '.($name?:'Principal'));$_SESSION['flash']='Ativação criada.';
 }
 if($a==='edit'){
  $id=(int)$_POST['id'];$st=db()->prepare('SELECT * FROM activations WHERE id=?');$st->execute([$id]);$old=$st->fetch();
  if($old){$device=trim((string)$_POST['device_id']);$server=(int)$_POST['server_id'];$name=trim((string)$_POST['list_name']);$u=trim((string)$_POST['username']);$p=(string)$_POST['password'];$exp=trim((string)($_POST['expires_at']??''));$primary=isset($_POST['is_primary'])?1:0;
   if($primary)db()->prepare('UPDATE activations SET is_primary=0 WHERE device_id=? AND id<>?')->execute([$device,$id]);
   $uEnc=$u!==''?encrypt_secret($u):(string)$old['username_enc'];$pEnc=$p!==''?encrypt_secret($p):(string)$old['password_enc'];
   db()->prepare('UPDATE activations SET device_id=?,server_id=?,list_name=?,username_enc=?,password_enc=?,expires_at=?,is_primary=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$device,$server,$name?:'Principal',$uEnc,$pEnc,$exp?:null,$primary,$id]);
   audit_log('activation.update','activation',$id,'Dispositivo '.$device.' • lista '.($name?:'Principal'));$_SESSION['flash']='Ativação atualizada.';
  }
 }
 if($a==='toggle'){$id=(int)$_POST['id'];db()->prepare('UPDATE activations SET is_active=1-is_active,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$id]);audit_log('activation.toggle','activation',$id);$_SESSION['flash']='Status atualizado.';}
 if($a==='delete'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM activations WHERE id=?')->execute([$id]);audit_log('activation.delete','activation',$id);$_SESSION['flash']='Ativação removida.';}
 if($a==='primary'){$id=(int)$_POST['id'];$st=db()->prepare('SELECT device_id FROM activations WHERE id=?');$st->execute([$id]);$device=$st->fetchColumn();if($device){db()->prepare('UPDATE activations SET is_primary=0 WHERE device_id=?')->execute([$device]);db()->prepare('UPDATE activations SET is_primary=1,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$id]);}audit_log('activation.primary','activation',$id);$_SESSION['flash']='Lista principal atualizada.';}
 header('Location:activations.php');exit;
}
$servers=db()->query('SELECT * FROM servers WHERE is_active=1 ORDER BY name')->fetchAll();
$rows=db()->query('SELECT a.*,s.name server_name,s.base_url FROM activations a JOIN servers s ON s.id=a.server_id ORDER BY a.id DESC')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT a.*,s.name server_name FROM activations a JOIN servers s ON s.id=a.server_id WHERE a.id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$pageTitle='Ativações e Listas';include __DIR__.'/partials/header.php';
?>
<?php if($f=$_SESSION['flash']??''){unset($_SESSION['flash']);?><div class="flash"><?=h($f)?></div><?php }?>
<div class="two-col"><section class="card"><h2><?=$edit?'Editar ativação':'Nova ativação'?></h2><?php if(!$servers):?><div class="notice">Cadastre primeiro um servidor DNS.</div><?php else:?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif?><div class="form-grid"><label>ID do dispositivo<input name="device_id" value="<?=h($edit['device_id']??'')?>" placeholder="Ex.: A1B2-C3D4-E5F6" required></label><label>Servidor<select name="server_id" required><?php foreach($servers as $s):?><option value="<?=$s['id']?>" <?=($edit&&$edit['server_id']==$s['id'])?'selected':''?>><?=h($s['name'])?></option><?php endforeach?></select></label><label>Nome da lista<input name="list_name" value="<?=h($edit['list_name']??'Principal')?>"></label><label>Validade<input type="date" name="expires_at" value="<?=h($edit['expires_at']??'')?>"></label><label>Usuário<input name="username" <?=$edit?'placeholder="Deixe vazio para manter"':'required'?>></label><label>Senha<input type="password" name="password" <?=$edit?'placeholder="Deixe vazio para manter"':'required'?>></label></div><label><span><input type="checkbox" name="is_primary" <?=(!$edit||$edit['is_primary'])?'checked':''?> style="width:auto"> Definir como lista principal</span></label><div class="actions"><button class="btn"><?=$edit?'Salvar alterações':'Ativar dispositivo'?></button><?php if($edit):?><a class="btn dark" href="activations.php">Cancelar</a><?php endif?></div></form><?php endif?></section>
<section class="card"><h2>Múltiplas listas</h2><p class="muted">Agora um mesmo dispositivo pode receber várias listas. O app mostra a tela <b>Minhas Listas</b> para alternar entre elas sem refazer a ativação.</p><a class="btn blue" href="public_activation.php" target="_blank">Abrir ativação pública</a></section></div>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Dispositivo</th><th>Lista</th><th>Servidor</th><th>Validade</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">Nenhuma ativação cadastrada.</td></tr><?php endif?><?php foreach($rows as $r):?><tr><td><span class="code"><?=h($r['device_id'])?></span></td><td><b><?=h($r['list_name'])?></b> <?=$r['is_primary']?'<span class="badge">Principal</span>':''?></td><td><?=h($r['server_name'])?></td><td><?=h($r['expires_at']?:'Sem data')?></td><td><span class="badge <?=$r['is_active']?'':'off'?>"><?=$r['is_active']?'Ativa':'Desativada'?></span></td><td><div class="actions"><a class="btn blue" href="?edit=<?=$r['id']?>">Editar</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="primary"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn dark">Principal</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn dark">Ativar/pausar</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" data-confirm="Excluir esta ativação?">Excluir</button></form></div></td></tr><?php endforeach?></tbody></table></div></section>
<?php include __DIR__.'/partials/footer.php'; ?>
